      "teacher_notes": {
        "primer": "This enquiry examines the causal chain leading from imperial victory in the Seven Years’ War to the outbreak of colonial rebellion in America. Students analyse how British national debt prompted Parliament to tax colonial commerce, explore the constitutional friction behind \"No taxation without representation\", investigate Paul Revere’s propaganda after the Boston Massacre, and evaluate the economic and political catalysts behind the 1773 Boston Tea Party.",
        "objectives": [
          {
            "objective": "Explain why the Seven Years’ War created imperial debt and prompted new colonial taxation.",
            "primer": "Guide students through Paragraph [4.1]. Highlight the contrast between victory over France and the severe financial burden (£133m debt) that prompted Grenville’s tax policies.",
            "question": "Hinge Question: Was it reasonable for the British government to expect American colonists to pay toward their own military defence?"
          },
          {
            "objective": "Analyse the ideological argument behind \"No taxation without representation\" during the Stamp Act crisis.",
            "primer": "Examine Paragraph [4.2]. Connect colonial grievances to the 1689 Bill of Rights studied in the previous unit, emphasising that colonists saw themselves as defending historic English liberties.",
            "question": "Hinge Question: Why were American colonists so outraged by a tiny stamp duty when people living in England were already paying far higher taxes?"
          },
          {
            "objective": "Deconstruct Paul Revere’s Boston Massacre engraving as a piece of political propaganda.",
            "primer": "Direct students to Paragraph [4.3] and Source A. Have students contrast Revere’s orderly firing-squad image with historical eyewitness accounts of an aggressive, snowball-throwing mob.",
            "question": "Hinge Question: What visual techniques did Paul Revere use to persuade viewers that the British redcoats were cold-blooded murderers?"
          }
        ]
      },
      "prologue": "Following the Seven Years' War, Parliament insisted that American colonists help pay for imperial defence. Colonists furiously resisted, shouting 'No taxation without representation!' In December 1773, Boston rebels disguised themselves as Native Americans and dumped 342 chests of British tea into the harbour. Why did imperial taxes push loyal subjects toward rebellion?",
