      "teacher_notes": {
        "primer": "This synoptic capstone enquiry investigates the climax and fracture of the First British Empire. Students evaluate the outbreak of armed rebellion at Lexington, deconstruct the Enlightenment principles of the 1776 Declaration alongside the painful reality of chattel slavery, analyse how French intervention and the siege of Yorktown led to British defeat, and examine the experiences of the Black Loyalists who gained freedom fighting for the Crown.",
        "objectives": [
          {
            "objective": "Explain why armed conflict began at Lexington and Concord and how Washington took command.",
            "primer": "Guide students through Paragraph [5.1]. Contrast the British regular army’s discipline with colonial militia tactics, and examine Dunmore’s shocking move to arm enslaved labourers.",
            "question": "Hinge Question: Why did Lord Dunmore’s offer of freedom to enslaved people cause more terror among American rebels than British cannons?"
          },
          {
            "objective": "Analyse the central moral paradox of the 1776 Declaration of Independence.",
            "primer": "Examine Paragraph [5.2] and Source A. Challenge students to reconcile Jefferson’s words \"all men are created equal\" with his ownership of over 170 human beings, referencing Dr Samuel Johnson’s critique.",
            "question": "Hinge Question: Can a document genuinely stand for universal human liberty when 41 of its 56 signatories were slaveholders?"
          },
          {
            "objective": "Synthesise the military reasons for British defeat and the historical significance of the Black Loyalists.",
            "primer": "Read Paragraphs [5.3], [5.4], and [5.5] and examine Source B. Trace how French naval intervention at Yorktown decided the war, and analyse why the evacuation of 3,000 Black Loyalists in the Book of Negroes is a vital historical turning point.",
            "question": "Hinge Question: Did Britain lose the American Revolutionary War because of American military brilliance or because France turned the conflict into an unwinnable global war?"
          }
        ]
      },
      "prologue": "In July 1776, American delegates proclaimed that 'all men are created equal' and declared independence from King George III. Yet thousands of enslaved Black Loyalists fled to British battle-lines, seeking genuine personal freedom under the Crown. At Yorktown in 1781, Britain surrendered. How did revolutionary ideals collide with imperial defeat and the reality of slavery?",
